'use strict';
const paths={book:'M4 4h6a3 3 0 0 1 2 3v14a4 4 0 0 0-4-2H4z M12 7a3 3 0 0 1 3-3h5v15h-4a4 4 0 0 0-4 2',chat:'M21 11a8 8 0 0 1-8 8H5l-3 3V11a9 9 0 0 1 19 0 M7 10h9 M7 14h6',translate:'M3 5h12 M9 2v3 M5 5c1 5 4 8 8 10 M12 5c-1 5-4 8-9 11 M14 21l4-11 4 11 M16 17h4',heart:'M20 4c-3-2-6 0-8 3-2-3-5-5-8-3-5 4 0 11 8 16 8-5 13-12 8-16Z',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M4 4l3 1 3-3h4l3 3 3-1 2 4-2 3 2 3-2 4-3-1-3 3h-4l-3-3-3 1-2-4 2-3-2-3z',down:'M6 9l6 6 6-6',arrow:'M9 5l7 7-7 7',back:'M15 5l-7 7 7 7',mic:'M9 5a3 3 0 0 1 6 0v7a3 3 0 0 1-6 0z M5 10v2a7 7 0 0 0 14 0v-2 M12 19v3 M8 22h8',send:'M22 2 9 15 M22 2l-8 20-5-7-7-5Z',sound:'M3 9h4l5-5v16l-5-5H3z M16 8a6 6 0 0 1 0 8 M19 5a10 10 0 0 1 0 14',music:'M9 18V5l11-2v13 M9 8l11-2 M9 18c0 4-6 4-6 1 0-3 6-4 6-1 M20 16c0 4-6 4-6 1 0-3 6-4 6-1',cup:'M4 8h13v8a5 5 0 0 1-5 5H9a5 5 0 0 1-5-5z M17 9h2a3 3 0 0 1 0 6h-2 M7 2v3 M12 2v3',check:'M5 12l4 4L20 5',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2',dictionary:'M5 3h14v18H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2 M3 17h16 M8 7h7 M8 11h5',play:'M8 4l12 8-12 8Z',pause:'M8 4v16 M16 4v16',swap:'M3 7h17l-4-4 M21 17H4l4 4',search:'M11 3a8 8 0 1 0 0 16 8 8 0 0 0 0-16 M17 17l5 5'};
const I=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.chat}"/></svg>`;
const E=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const app=document.querySelector('#app'), sheet=document.querySelector('#sheet');
const state={draft:'',translation:'아이스커피 한 잔 주세요.',translationMode:'text',translated:true,studyMode:'conversation',shelf:'phrases',musicStep:'use',line:1,answer:null,played:false,saved:new Set(),messages:[]};
const song=[{text:'今日も、いい日だね。',reading:'쿄오모, 이이 히다네',meaning:'오늘도 좋은 날이네요.'},{text:'ゆっくり歩こう。',reading:'윳쿠리 아루코오',meaning:'천천히 걸어요.'},{text:'小さな一歩から。',reading:'치이사나 잇포카라',meaning:'작은 한 걸음부터.'},{text:'一緒なら、楽しいね。',reading:'잇쇼나라, 타노시이네',meaning:'함께라면 즐겁네요.'}];
const mainNav=[['study','book','스터디','회화 · 단어 · 음악'],['chat','chat','AI 대화','배운 말로 이야기해요'],['translate','translate','번역','필요한 말을 바로'],['library','heart','보관함','내 표현 · 단어장']];
const allowed=['study','chat','translate','music','library'];
let current=allowed.includes(location.hash.slice(1))?location.hash.slice(1):'chat';
if(new URLSearchParams(location.search).has('frame'))document.body.classList.add('framed');
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2600);}
function dialog(title,html){document.querySelector('#sheet-body').innerHTML=`<h2 id="sheet-title">${title}</h2>${html}`;sheet.showModal();}
function go(view){if(view===current){render(true);return;}location.hash=view;}
function nav(desktop=false){const selected=current==='music'?'study':current;return `<nav class="${desktop?'':'bottom-nav'}" aria-label="${desktop?'PC 주요 메뉴':'주요 메뉴'}">${mainNav.map(([id,icon,label,sub])=>`<button data-go="${id}" aria-current="${selected===id?'page':'false'}">${I(icon)}<span>${label}${desktop?`<small>${sub}</small>`:''}</span></button>`).join('')}</nav>`;}
function modeNav(){const selected=current==='music'?'music':state.studyMode;return `<nav class="segmented${current==='music'?' music-mode-nav':''}" aria-label="학습 방식">${[['conversation','chat','회화'],['words','dictionary','단어'],['music','music','음악']].map(([id,ic,label])=>`<button data-action="study-mode" data-value="${id}" aria-pressed="${selected===id}">${I(ic)}${label}</button>`).join('')}</nav>`;}
function study(){const words=state.studyMode==='words';return `<div class="study-intro"><h1>${words?'단어부터 차근차근,<br>내 말로 익혀요.':'오늘은 어떤 말을<br>배워볼까요?'}</h1><p>하루 5분, 조금씩 더 자연스럽게.</p></div>${modeNav()}<section class="lesson-hero"><div class="lesson-meta"><span>${words?'입문 단어':'카페에서 주문하기'}</span><span>${words?'단어 5개':'문장 3 / 10'}</span></div><span class="lesson-symbol">${I(words?'dictionary':'cup')}</span><h2 lang="ja">${words?'コーヒー':'一つください。'}</h2><p>${words?'커피 한 잔에서 시작하는 다섯 단어':'한 잔 주세요. 익힌 말부터 이어가요.'}</p><div class="lesson-footer"><button class="button-line primary" data-action="${words?'word-card':'lesson'}">${words?'단어 익히기':'이어서 연습'}${I('arrow')}</button><small>레벨 1 · 입문</small></div></section><div class="section-title"><h2>잊기 전에, 한 번 더</h2><span>복습할 표현 3개</span></div><div class="review-row"><span class="review-icon">${I('clock')}</span><div><p>아이스커피 한 잔 주세요.</p><small>번역에서 모은 표현</small></div><button class="icon-button" data-go="library" aria-label="복습 표현 열기">${I('arrow')}</button></div><div class="section-title music-discovery"><h2>노래로 만나볼까요?</h2></div><div class="review-row music-entry"><span class="review-icon">${I('music')}</span><div><p>작은 한 걸음, 한 줄부터</p><small>듣고 익힌 말을 대화에 써 봐요</small></div><button class="icon-button" data-go="music" aria-label="음악 학습 열기">${I('arrow')}</button></div><div class="level-summary"><span>레벨 1</span><small>8개 상황 중 3개 완료</small><div class="progress-line"><i></i></div></div>`;}
function chat(){return `<div class="screen-heading chat-heading"><div><small>AI 대화</small><h1>카페에서 주문하기</h1></div><button class="icon-button context-switch" data-action="context" aria-label="연습 상황 바꾸기">${I('swap')}</button></div><p class="chat-goal">틀려도 괜찮아요. 편하게 이야기해요.</p><div class="message user"><div class="bubble">아이스커피를 주문하고 싶어요.</div></div><div class="message"><div class="speaker-label"><span class="mini-mark">ㅎ</span>한마디<span class="speaker-detail">일본어 대화 친구</span></div><div class="bubble"><p class="foreign" lang="ja">アイスコーヒーですね。<br>サイズはどうしますか？</p><p class="reading">아이스 코오히이데스네.<br>사이즈와 도오시마스카?</p><p class="meaning">아이스커피군요.<br>사이즈는 어떻게 하시겠어요?</p><div class="bubble-tools"><button data-action="audio" aria-label="대화 문장 듣기">${I('sound')}듣기</button><button data-action="save" data-value="chat">${I(state.saved.has('chat')?'check':'heart')}${state.saved.has('chat')?'저장했어요':'표현 저장'}</button></div></div></div>${state.messages.map(m=>`<div class="message user"><div class="bubble">${E(m)}</div></div>`).join('')}<p class="suggestions-label">말문이 막힐 땐</p><div class="suggestions"><button data-action="suggest" data-value="미디엄 사이즈로 주세요.">미디엄으로 주세요${I('arrow')}</button><button data-action="suggest" data-value="여기서 마실게요.">여기서 마실게요${I('arrow')}</button></div>`;}
function composer(){return `<div class="composer"><form id="chat-form" class="composer-inner"><p class="draft-note">${I('check')}한국어로 입력해도 괜찮아요.</p><div class="compose-row"><button class="voice" type="button" data-action="voice" aria-label="음성으로 입력">${I('mic')}</button><label class="sr-only" for="chat-input">대화 메시지</label><textarea id="chat-input" rows="1" maxlength="1000" placeholder="하고 싶은 말을 적어보세요">${E(state.draft)}</textarea><button class="send" type="submit" aria-label="메시지 보내기">${I('send')}</button></div><p class="compose-hint">학습하고 싶은 말만 입력해 주세요. AI 답변은 틀릴 수 있어요.</p></form></div>`;}
function translation(){return `<div class="screen-heading"><div><h1>어떤 말을 전할까요?</h1><small>내 말이 자연스럽게 닿도록.</small></div></div><div class="translation-languages"><span>한국어</span>${I('swap')}<span>일본어</span></div><div class="segmented two" aria-label="번역 입력 방식"><button data-action="translation-mode" data-value="text" aria-pressed="${state.translationMode==='text'}">${I('dictionary')}직접 입력</button><button data-action="translation-mode" data-value="voice" aria-pressed="${state.translationMode==='voice'}">${I('mic')}말하기</button></div>${state.translationMode==='text'?`<form id="translation-form"><label class="input-label" for="translation-input">번역할 말</label><textarea class="translation-input" id="translation-input" maxlength="1000">${E(state.translation)}</textarea><button class="primary full button-line" type="submit">번역하기${I('arrow')}</button></form>`:`<div class="voice-panel"><button class="mic-large" data-action="voice" aria-label="번역 음성 입력 시작">${I('mic')}</button><small>눌러서 말하기 · 한 번에 한 사람씩</small></div><button class="text-button" data-action="translation-mode" data-value="text">직접 입력으로 바꾸기</button>`}${state.translated?`<section class="translation-result"><div class="result-label"><span>일본어</span><button class="icon-button" data-action="audio" aria-label="번역 문장 듣기">${I('sound')}</button></div><p class="foreign" lang="ja">アイスコーヒーを<br>一つください。</p><p class="reading">아이스 코오히이오 히토츠 쿠다사이.</p><p class="result-meaning">아이스커피 한 잔 주세요.</p><button class="save-result" data-action="save" data-value="translation">${I(state.saved.has('translation')?'check':'heart')}${state.saved.has('translation')?'보관함에 저장했어요':'이 표현을 내 학습에 저장'}</button></section>`:''}`;}
function miniPlayer(){return `<div class="mini-player"><button data-action="play" aria-label="${state.played?'연습곡 일시정지':'연습곡 재생'}">${I(state.played?'pause':'play')}</button><div class="player-track"><p>小さな一歩</p><div class="time-track"><span>0:12</span><div class="progress-line"><i></i></div><span>0:32</span></div></div><small>1×</small><button data-action="lyrics" aria-label="전체 가사 보기">${I('book')}</button></div>`;}
function music(){const line=song[state.line];const q=[{word:'今日',correct:'오늘',choices:['내일','오늘','어제']},{word:'ゆっくり',correct:'천천히',choices:['빠르게','천천히','가끔']},{word:'一歩',correct:'한 걸음',choices:['한 사람','한 걸음','한 시간']},{word:'一緒',correct:'함께',choices:['혼자','함께','먼저']}][state.line];const steps=[['listen','듣기'],['repeat','따라하기'],['use','활용'],['review','복습']];return `${modeNav()}<div class="music-heading"><span class="record">${I('music')}</span><div><small>한마디 연습곡 · 입문</small><h1 lang="ja">小さな一歩</h1></div></div><ol class="music-steps" aria-label="음악 학습 단계">${steps.map(([id,label],i)=>`<li><button data-action="music-step" data-value="${id}" aria-current="${state.musicStep===id?'step':'false'}"><span class="step-number">${i+1}</span>${label}</button></li>`).join('')}</ol>${miniPlayer()}<div class="practice-top"><h2>${{listen:'가까이 듣고, 뜻을 만나요',repeat:'한 줄씩 따라 말해요',use:'한 단어를 내 말로',review:'기억한 뜻을 떠올려요'}[state.musicStep]}</h2><span>${state.line+1} / 4줄</span></div><section class="lyric-focus"><p class="foreign" lang="ja">${line.text}</p><p class="reading">${line.reading}</p><p class="meaning">${line.meaning}</p></section>${state.musicStep==='use'||state.musicStep==='review'?`<section class="word-question"><div class="word-title"><span lang="ja">${q.word}</span><button class="icon-button" data-action="audio" aria-label="단어 발음 듣기">${I('sound')}</button></div><p class="question">이 단어는 어떤 뜻일까요?</p><div class="choices" aria-label="뜻 선택">${q.choices.map(a=>`<button data-action="answer" data-value="${a}" class="${state.answer===a?(a===q.correct?'correct':'wrong'):''}">${a===q.correct&&state.answer===a?'✓ ':''}${a}</button>`).join('')}</div>${state.answer?`<p class="answer-feedback" role="status">${state.answer===q.correct?`맞았어요. ‘${q.correct}’라는 뜻이에요.`:'한 번 더 골라 보세요.'}</p>`:''}</section>`:`<section class="word-question"><p>${state.musicStep==='listen'?'선택한 줄의 노래를 듣고, 발음과 뜻을 함께 확인해요.':'노래를 들은 뒤 한 줄을 소리 내어 따라 해 보세요.'}</p><button class="button-line full" style="margin-top:15px" data-action="${state.musicStep==='listen'?'play':'repeated'}">${I(state.musicStep==='listen'?'play':'check')}${state.musicStep==='listen'?'이 줄 듣기':'따라 말했어요'}</button></section>`}<div class="practice-actions"><button data-action="save" data-value="word">${I(state.saved.has('word')?'check':'dictionary')}${state.saved.has('word')?'저장했어요':'단어 저장'}</button><button data-action="use-chat">${I('chat')}대화에 써보기</button></div><div class="next-line"><small>한 줄씩, 내 말이 되도록</small><button data-action="next-line">다음 줄${I('arrow')}</button></div>`;}
function library(){return `<div class="screen-heading"><div><h1>내가 모은 한마디</h1><small>마음에 남은 말을, 오래 기억해요.</small></div><span class="context-pill">오늘 복습 3</span></div><nav class="segmented two" aria-label="보관함 보기"><button data-action="shelf" data-value="phrases" aria-pressed="${state.shelf==='phrases'}">내 표현 ${12+state.saved.size}</button><button data-action="shelf" data-value="words" aria-pressed="${state.shelf==='words'}">단어장 8</button></nav><input class="library-search" id="library-search" aria-label="보관함 검색" placeholder="저장한 말을 찾아보세요"><div id="library-items">${state.shelf==='phrases'?`<article class="library-item"><div class="item-top"><small>번역에서 모은 말</small><span class="tag">오늘 복습</span></div><p class="foreign" lang="ja">アイスコーヒーを一つください。</p><p class="reading">아이스 코오히이오 히토츠 쿠다사이.</p><p class="meaning">아이스커피 한 잔 주세요.</p><div class="bubble-tools"><button data-action="audio">${I('sound')}듣기</button><button data-go="chat">${I('chat')}대화에 써보기</button></div></article><article class="library-item"><div class="item-top"><small>음악에서 모은 말</small><span class="tag">오늘 복습</span></div><p class="foreign" lang="ja">ゆっくり歩こう。</p><p class="meaning">천천히 걸어요.</p><div class="bubble-tools"><button data-action="audio">${I('sound')}듣기</button><button data-action="use-chat">${I('chat')}대화에 써보기</button></div></article>`:`<article class="library-item"><div class="item-top"><small>음악에서 모은 단어</small><span class="tag">오늘 복습</span></div><p class="foreign" lang="ja">ゆっくり</p><p class="reading">윳쿠리 · 천천히</p><p class="meaning">ゆっくり歩こう。 · 천천히 걸어요.</p><div class="bubble-tools"><button data-action="audio">${I('sound')}듣기</button><button data-action="word-card">뜻 가리고 복습</button></div></article>`}</div>`;}
function aside(){if(current==='music')return `<h2>지금 듣는 곡의 가사</h2><p>선택한 줄의 연습을 바로 이어가요.</p><ol class="lyrics-list">${song.map((l,i)=>`<li class="${state.line===i?'selected':''}"><small>${String(i+1).padStart(2,'0')}</small><p lang="ja">${l.text}</p><small>${l.meaning}</small><button class="text-button" data-action="pick-line" data-value="${i}">이 줄 연습</button></li>`).join('')}</ol><div class="aside-note">현재 단계와 선택한 줄을 유지해<br>듣기와 연습을 오갈 수 있어요.</div>`;return `<h2>${current==='chat'?'지금 쓸 수 있는 표현':'오늘의 한마디'}</h2><p>짧게 익히고, 직접 써 보세요.</p><div class="aside-card"><strong lang="ja">一つください。</strong><p>히토츠 쿠다사이.</p><p>하나 주세요.</p><button class="text-button" data-action="suggest" data-value="하나 주세요.">대화에 넣기</button></div><div class="aside-card"><strong lang="ja">ここで飲みます。</strong><p>코코데 노미마스.</p><p>여기서 마실게요.</p><button class="text-button" data-action="suggest" data-value="여기서 마실게요.">대화에 넣기</button></div><div class="aside-note">오늘 복습할 표현 3개<br>보관함에서 이어서 연습해요.</div>`;}
function render(focus=false){const title={study:'스터디',chat:'AI 대화',translate:'번역',music:'음악 학습',library:'보관함'}[current];app.dataset.view=current;app.innerHTML=`<a class="skip-link" href="#screen">학습 내용으로 바로 가기</a><aside class="sidebar"><div class="wordmark"><span class="brand-mark">ㅎ</span>한마디</div>${nav(true)}<p class="sidebar-note">하루 한마디,<br>내 말이 되도록.</p></aside><header class="topbar">${current==='music'?`<button class="study-back" data-go="study" aria-label="스터디로 돌아가기">${I('back')}<span>스터디로</span></button>`:`<div class="wordmark"><span class="brand-mark">ㅎ</span><span class="mobile-wordmark">${innerWidth>=1000?title:'한마디'}</span></div>`}<div class="top-actions"><button class="language" data-action="language" aria-label="학습 언어 일본어"><span class="dot"></span>일본어${I('down')}</button><button class="icon-button" data-action="settings" aria-label="학습 설정">${I('settings')}</button></div></header><div class="workspace"><main class="content" id="screen" tabindex="-1" aria-label="${title}"><div class="content-inner">${{study,chat,translate:translation,music,library}[current]()}</div></main>${current==='chat'?composer():''}<aside class="aside-panel" aria-label="학습 참고">${aside()}</aside></div>${nav()}`;if(focus)document.querySelector('#screen').focus({preventScroll:true});}
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(allowed.includes(next)){current=next;render(true);}});
window.addEventListener('resize',()=>{const el=document.querySelector('.mobile-wordmark');if(el)el.textContent=innerWidth>=1000?{study:'스터디',chat:'AI 대화',translate:'번역',music:'음악 학습',library:'보관함'}[current]:'한마디';});
document.addEventListener('input',e=>{if(e.target.id==='chat-input')state.draft=e.target.value;if(e.target.id==='translation-input')state.translation=e.target.value;if(e.target.id==='library-search'){const term=e.target.value;document.querySelectorAll('.library-item').forEach(el=>el.hidden=!el.textContent.includes(term));}});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='chat-form'){if(!state.draft.trim()){toast('하고 싶은 말을 입력해 주세요.');return;}state.messages.push(state.draft);state.draft='';render();toast('시안의 전송 예시예요. 실제 AI 요청은 보내지 않아요.');}if(e.target.id==='translation-form'){if(!state.translation.trim()){toast('번역할 말을 입력해 주세요.');return;}state.translated=true;render();toast('예시 번역 결과를 보여드려요.');}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.classList.contains('close-sheet')){sheet.close();return;}if(b.dataset.go){go(b.dataset.go);return;}const a=b.dataset.action,v=b.dataset.value;switch(a){case'study-mode':if(v==='music')go('music');else{state.studyMode=v;go('study');}break;case'translation-mode':state.translationMode=v;render();break;case'suggest':state.draft=v;if(current!=='chat')go('chat');else{document.querySelector('#chat-input').value=v;document.querySelector('#chat-input').focus();}break;case'save':state.saved.add(v);render();toast(v==='word'?'단어장에 저장했어요.':'보관함에 표현을 저장했어요.');break;case'music-step':state.musicStep=v;state.answer=null;render();break;case'answer':state.answer=v;render();break;case'next-line':state.line=(state.line+1)%song.length;state.answer=null;render();break;case'pick-line':state.line=Number(v);state.answer=null;render();break;case'use-chat':state.draft=`‘${song[state.line].text}’를 써서 대화하고 싶어요.`;go('chat');toast('음악에서 배운 표현을 대화 입력에 넣었어요.');break;case'play':state.played=!state.played;render();toast('재생 버튼의 시안 예시예요. 실제 소리는 나오지 않아요.');break;case'audio':case'voice':toast(a==='voice'?'음성 입력의 시안 예시예요. 실제 녹음은 하지 않아요.':'발음 듣기의 시안 예시예요.');break;case'lyrics':dialog('작은 한 걸음 · 전체 가사',`<ol class="lyrics-list">${song.map((l,i)=>`<li class="${state.line===i?'selected':''}"><small>${i+1}번째 줄</small><p lang="ja">${l.text}</p><small>${l.meaning}</small></li>`).join('')}</ol>`);break;case'shelf':state.shelf=v;render();break;case'language':dialog('학습 언어','<p>이 시안은 일본어 예시로 구성했어요.</p><p>실제 앱에서는 언어별 학습 기록과 작성 중인 말을 구분해 관리합니다.</p>');break;case'settings':dialog('학습 설정','<p>학습 언어: 일본어</p><p>연습 단계: 1 · 한마디 시작</p><p>하루 연습: 5분</p><p>색상·버튼·입력 상태는 웹과 앱에 같은 기준을 적용할 예정이에요.</p>');break;case'context':dialog('어떤 상황을 연습할까요?','<p>현재는 카페에서 주문하는 대화 예시예요.</p><button class="primary full close-sheet">카페 · 주문하기로 연습</button>');break;case'lesson':dialog('카페에서 주문하기','<small>문장 3 / 10 · 이어서 연습</small><div class="word-reveal"><b lang="ja">ここで飲みます。</b><p>코코데 노미마스.</p><p>여기서 마실게요.</p></div><button class="primary full close-sheet">이 문장으로 연습하기</button>');break;case'word-card':dialog('단어 1 / 5 · 천천히','<div class="word-reveal"><b lang="ja">ゆっくり</b><p>윳쿠리</p></div><button class="primary full" data-action="reveal-word">뜻 확인하기</button>');break;case'reveal-word':dialogReveal();break;case'repeated':state.musicStep='use';render();toast('활용 단계로 이어졌어요.');break;}});
function dialogReveal(){document.querySelector('#sheet-body').innerHTML='<h2 id="sheet-title">ゆっくり · 천천히</h2><div class="word-reveal"><b>천천히</b><p>ゆっくり歩こう。</p><p>천천히 걸어요.</p></div><p>실제 학습에서는 뜻 퀴즈와 복습 기록으로 이어져요.</p>';}
render();
